#!/usr/bin/env python3
"""Build the optional authenticated static entry from the canonical UI fragment.

No bundler or installed packages: the application uses native JavaScript/CSS.
Only module-owned output may be generated, and --check is read-only.
"""
import argparse
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
STATIC = ROOT / "bili_remote/static/v2/workbench"
FRAGMENT = ROOT / "bili_remote/templates/v2/workbench/workbench.html"


def document():
    fragment = FRAGMENT.read_text()
    return '''<!doctype html>
<!-- Generated by tests/v2/workbench/build_frontend.py; edit the canonical template. -->
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="csrf-token" content="">
<meta name="referrer" content="no-referrer">
<title>发种工作台 · Bili Remote</title>
<link rel="stylesheet" href="/static/v2/workbench/workbench.css">
<script defer src="/static/v2/workbench/api.js"></script>
<script defer src="/static/v2/workbench/preview.js"></script>
<script defer src="/static/v2/workbench/workbench.js"></script>
<script defer src="/static/v2/workbench/standalone.js"></script>
</head>
<body class="wb-entry-body">
<p class="wb-entry-status" data-entry-status role="status">正在检查登录状态…</p>
''' + fragment.replace('data-workbench aria-label', 'data-workbench hidden aria-label', 1) + '''
</body>
</html>
'''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    for script in STATIC.glob('*.js'):
        subprocess.run(['node', '--check', str(script)], check=True)
    target = STATIC / 'index.html'
    expected = document()
    if args.check:
        assert target.read_text() == expected, 'Static entry is stale: run build_frontend.py'
    else:
        target.write_text(expected)
    print('Frontend build verified: native JS/CSS, canonical fragment and static entry agree.')


if __name__ == '__main__':
    main()
